"""Inventory/disassemble local CAM camera scripts; generated bytes stay ignored.

Table routing: CameraResetAll / EventCamSetScript. Command spans and relative
jump semantics: CameraScriptRun MIPS. This is analysis, not a runtime VM.
"""
import collections
import argparse
import json
import struct
from pathlib import Path
from datetime import datetime
from area_tables import ROOT, EXE, area_members, area_records
from mips_ground_reference import Reference

WORDS = {1:2, 2:1, 3:2, 4:2, 5:1, 6:2, 7:2, 8:2, 9:2, 10:1, 11:1,
         12:1, 13:3, 14:1, 15:1, 16:4, 17:4, 18:3, 19:5, 20:8, 21:4,
         22:2, 23:3, 24:4, 25:8, 26:3}
YIELD = {1, 2, 6, 7, 8, 9, 18, 19, 20, 23, 25}


def u16(data, at):
    if at < 0 or at+2 > len(data) or at % 2:
        raise ValueError(f'halfword outside aligned blob: {at:X}')
    return struct.unpack_from('<H', data, at)[0]


def decode(blob, start, limit=None):
    limit = len(blob) if limit is None else limit
    seen = set(); rows = []; pc = start
    while pc not in seen:
        if not 0 <= pc < limit:
            raise ValueError('camera command target outside bounded section')
        seen.add(pc); op = u16(blob, pc)
        if op not in WORDS:
            raise ValueError(f'unknown camera opcode {op:X} at {pc:X}')
        end = pc+WORDS[op]*2
        if end > limit:
            raise ValueError('camera operands outside bounded section')
        operands = [struct.unpack_from('<h', blob, pc+2+i*2)[0] for i in range(WORDS[op]-1)]
        following = pc+2+operands[0] if op == 1 else end
        rows.append(dict(offset=pc, opcode=op, operands=operands, next=following,
                         yields=op in YIELD, dynamic_pointer=op == 22))
        if op == 2:
            return rows, 'remove'
        pc = following
        if len(rows) > 10000:
            raise ValueError('camera decode budget exceeded')
    return rows, 'cycle'


def inventory():
    scripts=[]; areas=[]; counts=collections.Counter(); executions=0
    for area, member in sorted(area_members().items()):
        blob=(ROOT/f'extract/members/{member:03X}.bin').read_bytes()
        cam=struct.unpack_from('<I',blob,0x4D8)[0]
        if not cam:
            areas.append(dict(area=area, member=member, regions=0, scripts=0)); continue
        if blob[cam:cam+3] != b'CAM':raise ValueError('missing CAM header')
        regions=u16(blob,cam+4)
        if not regions:
            # Original empty Fossil CAM has +E=0, not a valid name-table pointer.
            areas.append(dict(area=area, member=member, regions=0, scripts=0)); continue
        table=cam+u16(blob,cam+14); count=u16(blob,table)
        if table+8+40*count>len(blob):raise ValueError('name table exceeds blob')
        ref=Reference(blob)
        ref.write(0x800B4D40,4,0x80130000)
        ref.write(0x800E6924,4,0x80154000+table)
        ref.write(0x800E692C,4,0x80154000+table+8)
        for i in range(count):
            entry=table+8+i*40; flags=u16(blob,entry); start=table+u16(blob,entry+2)
            name=blob[entry+8:entry+40].split(b'\0',1)[0].decode('ascii')
            commands,ending=decode(blob,start)
            # Full original table routing, including offset relative to TABLE.
            ref.ram[0x130000:0x1300B0]=bytes(0xB0)
            ref.call(0x8004BAD8,(0,i,(flags>>13)&3,1))
            assert ref.read(0x80130084,4)==0x80154000+start
            assert ref.read(0x80130088,2)==0 and ref.read(0x8013008A,2)==0
            assert ref.read(0x8013008E,1)==(flags>>13)&3
            fetched=[]
            def trace(pc,regs):
                if pc==0x8004C37C:fetched.append(regs[16]-0x80154000)
            ref.trace=trace
            ref.call(0x8004C318,(0x80130000,),hooks={0x80047290:lambda cpu,regs:0})
            ref.trace=None
            first=[]
            for command in commands:
                first.append(command['offset'])
                if command['yields']:break
            assert fetched==first,(area,i,fetched,first)
            last=commands[len(first)-1]
            assert ref.read(0x80130084,4)==0x80154000+last['next'],(area,i)
            executions+=1
            counts.update(command['opcode'] for command in commands)
            handlers=[command['operands'][1]&255 for command in commands if command['opcode']==23]
            scripts.append(dict(area=area,member=member,index=i,name=name,flags=flags,
                                start=start,ending=ending,handlers=handlers,commands=commands))
        areas.append(dict(area=area,member=member,regions=regions,scripts=count))
    report=dict(areas=len(areas), areas_with_scripts=sum(bool(a['scripts']) for a in areas),
                local_scripts=len(scripts), reachable_commands=sum(counts.values()),
                opcode_counts={f'{k:02X}':v for k,v in sorted(counts.items())},
                scripts_with_indexed_handler=sum(bool(s['handlers']) for s in scripts),
                original_table_routes=executions, original_first_yield_runs=executions,
                failures=0)
    symbols={line.split(',',2)[0].lower():line.split(',',2)[1] for line in
             (ROOT/'tools/symbols.csv').read_text().splitlines()
             if line and not line.startswith('#') and ',' in line}
    chains={row['area']:row['chain'] for row in area_records()}
    base,size=struct.unpack_from('<II',EXE,0x18)
    handlers=[]
    for script in scripts:
        for index in script['handlers']:
            address=ref.read(0x800AF140+index*4,4);overlay=None
            if base<=address<base+size:
                key=f'{address:08x}'
            else:
                hits=[member for member,post,dest in chains[script['area']]
                      if member>=0x180 and post==0 and
                      dest<=address<dest+(ROOT/f'extract/members/{member:03X}.bin').stat().st_size]
                if len(hits)!=1:raise ValueError('camera handler has no unique loaded code overlay')
                overlay=hits[0];key=f'ovl_{overlay:03x}::{address:08x}'
            name=symbols.get(key)
            if not name:name='unlabelled entry (bounds validated; behavior pending)'
            handlers.append(dict(area=f'{script["area"]:02X}',index=index,address=f'{address:08X}',
                                 overlay=f'{overlay:03X}' if overlay else 'resident',name=name))
    report['indexed_handlers']=handlers
    report['handlers_without_symbols']=sum(h['name'].startswith('unlabelled') for h in handlers)
    return report,areas,scripts


def main(propose=False):
    report,areas,scripts=inventory()
    out=ROOT/'extract/codex/native/camera-scripts.json'
    # Bounds/unknown/relative-loop decoder guards, not original execution cases.
    for blob,start,limit in ((b'\0\0',0,None),(b'\3\0',0,None),
                             (b'\2\0',1,None),(b'\1\0\xff\x7f',0,None)):
        try:decode(blob,start,limit)
        except ValueError:pass
        else:raise AssertionError('malformed script accepted')
    rows,ending=decode(struct.pack('<hh',1,-2),0)
    assert len(rows)==1 and ending=='cycle'
    report['decoder_guard_checks']=5
    ref=Reference((ROOT/'extract/members/05B.bin').read_bytes())
    for case in range(256):
        controls=bytearray((case+i*31)&255 for i in range(80))
        ref.ram[0xE68D0:0xE6920]=controls
        ref.call(0x8004B580)
        controls[0x42]=1
        assert ref.ram[0xE68D0:0xE6920]==controls
    report['original_force_follow_leaf_checks']=256
    out.write_text(json.dumps(dict(report=report,areas=areas,scripts=scripts),indent=2)+'\n')
    lines=['# Local area camera script inventory','',
           'Generated by tools/codex/camera_scripts.py from all actual area members.','',
           *[f'- {key}: {value}' for key,value in report.items() if key != 'indexed_handlers'], '',
           'CAM byte offset is blob+0x4D8. Nonempty region sections use the name table at',
           'CAM+u16(header+0xE): header8, records40. Flags+0, script byte offset+2',
           '(relative to the name-table header), identifier32bytes+8. Original',
           'EventCamSetScript group1 routing and first CameraScriptRun yield execute',
           'for every named local script. Empty CAM sections are skipped explicitly.', '',
           'Command words are signed16 operands. Opcode1 jumps relative to its operand',
           'address and yields; opcode2 removes the linked slot. Decoding follows',
           'post-wait continuation until removal or a relative cycle. Opcode0x16 may',
           'replace the script through an external event; its listed continuation is',
           'static fallthrough, not a resolved dynamic call. It does not occur here.', '',
           'Only the observed six command types have actual-stream execution checks.',
           'Other command lengths come from original MIPS/static control flow. Group0',
           'event scripts at runtime0x80102800 are outside this local-area inventory;',
           'their backing resource and external indexed handlers remain separate.', '',
           'Handler addresses read from EXE table0x800AF140; names reuse existing symbols.', '',
           'Overlay handlers resolve through each area EXE load chain and member bounds;',
           'a repeated virtual address does not identify a shared function.', '',
           '| Area | Handler id | Entry | Overlay | Existing name |','|---|---|---|---|---|',
           *[f'| {h["area"]} | {h["index"]} | {h["address"]} | {h["overlay"]} | {h["name"]} |' for h in report['indexed_handlers']], '',
           '| Area | Member | Regions | Local scripts |','|---|---|---:|---:|',
           *[f'| {a["area"]:02X} | {a["member"]:03X} | {a["regions"]} | {a["scripts"]} |' for a in areas], '']
    (ROOT/'notes/port/validation/camera_scripts.md').write_text('\n'.join(lines))
    if propose:
        inbox=ROOT/'notes/codex-inbox.md'
        marker='Camera script handler entries from all local CAM streams'
        if marker in inbox.read_text():raise ValueError('handler proposal already exists')
        lines=[f'\n\n## {datetime.now().astimezone().isoformat(timespec="seconds")} — {marker} [status: open]',
               'Evidence: tools/codex/camera_scripts.py/.md; private notes/decomp/codex/camera-handler-boundaries.tsv and overnight-camera-handlers/.',
               'All252local scripts/12indexedhandler uses route through EXE table800AF140 and each area code-overlay chain; member bounds verified.',
               'Private headless boundary inspection defined missing negative-stack entries and the exact four-instruction resident force-follow leaf;12roots/23exports/0failures.',
               'Overlay names below identify proven area/dispatch role only; detailed handler behavior still pending. Resident force-follow behavior also executes256original cases.',
               'No matching addresses currently appear in symbols.csv. Add symbols:',
               'symbols (paste into tools/symbols.csv as a new batch):']
        for handler in report['indexed_handlers']:
            if handler['overlay']=='resident':
                lines.append('8004B580,CameraForceFollow,Sets CameraSelectMode force-follow flag at800E6912 to1; table800AF140 handler3 used by area2C.')
            else:
                lines.append(f'ovl_{handler["overlay"]}::{handler["address"]},Area{handler["area"]}_CameraScriptHandler{handler["index"]:02X},'
                             f'Proven localCAM opcode17 indexedhandler{handler["index"]} inarea{handler["area"]}; overlayloadchain/memberbounds/privatefunctionboundary checked; detailedbehavior pending.')
        with inbox.open('a',encoding='utf-8') as file:file.write('\n'.join(lines)+'\n')
    print(report)


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--propose',action='store_true')
    main(parser.parse_args().propose)
